{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_section_stack",
        "benefits_recommendations_h2",
        "key_benefits_h3",
        "key_benefits_list_stack",
        "recommended_exercise_h3",
        "aerobic_activity_stack",
        "strength_training_stack",
        "mind_body_stack",
        "duration_frequency_h3",
        "duration_frequency_list_stack",
        "quick_actions_h2",
        "quick_actions_stack",
        "sources_h2",
        "sources_list_stack"
      ]
    },
    "title_section_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "title_h2_1",
        "icon_person_walking",
        "intro_text"
      ]
    },
    "title_h2_1": {
      "type": "Text",
      "props": {
        "text": "Exercise for Young Adult Mental Well-being",
        "variant": "h2"
      },
      "children": []
    },
    "icon_person_walking": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000127_01_1_person-walking.svg"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Regular physical activity offers significant benefits for the mental health of young adults aged 18-25, helping to manage stress, improve mood, and enhance overall cognitive function during a critical developmental period."
      },
      "children": []
    },
    "benefits_recommendations_h2": {
      "type": "Text",
      "props": {
        "text": "Mental Health Benefits & Exercise Recommendations",
        "variant": "h2"
      },
      "children": []
    },
    "key_benefits_h3": {
      "type": "Text",
      "props": {
        "text": "Key Benefits",
        "variant": "h3"
      },
      "children": []
    },
    "key_benefits_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "benefit_stress_anxiety",
        "benefit_mood",
        "benefit_cognitive",
        "benefit_self_esteem",
        "benefit_sleep",
        "benefit_social"
      ]
    },
    "benefit_stress_anxiety": {
      "type": "Text",
      "props": {
        "text": "Reducing Stress & Anxiety: Physical activity lowers stress hormones like cortisol and releases endorphins, which have mood-boosting effects."
      },
      "children": []
    },
    "benefit_mood": {
      "type": "Text",
      "props": {
        "text": "Improving Mood: It acts as a natural antidepressant, alleviating symptoms of depression and enhancing overall emotional state."
      },
      "children": []
    },
    "benefit_cognitive": {
      "type": "Text",
      "props": {
        "text": "Enhancing Cognitive Function: Exercise boosts blood flow to the brain, improving memory, focus, and problem-solving skills."
      },
      "children": []
    },
    "benefit_self_esteem": {
      "type": "Text",
      "props": {
        "text": "Boosting Self-Esteem: Achieving fitness goals and improving physical health can lead to increased confidence and a more positive body image."
      },
      "children": []
    },
    "benefit_sleep": {
      "type": "Text",
      "props": {
        "text": "Promoting Better Sleep: Regular activity helps regulate sleep patterns, leading to deeper and more restorative sleep, which is crucial for mental resilience."
      },
      "children": []
    },
    "benefit_social": {
      "type": "Text",
      "props": {
        "text": "Increasing Social Connection: Group activities or sports can foster social interaction and reduce feelings of isolation."
      },
      "children": []
    },
    "recommended_exercise_h3": {
      "type": "Text",
      "props": {
        "text": "Recommended Exercise Types",
        "variant": "h3"
      },
      "children": []
    },
    "aerobic_activity_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "aerobic_title_icon_stack",
        "aerobic_description",
        "aerobic_examples_text"
      ]
    },
    "aerobic_title_icon_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "icon_bicycle",
        "aerobic_title"
      ]
    },
    "icon_bicycle": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000127_01_2_bicycle.svg"
      },
      "children": []
    },
    "aerobic_title": {
      "type": "Text",
      "props": {
        "text": "Aerobic Activity",
        "variant": "label"
      },
      "children": []
    },
    "aerobic_description": {
      "type": "Text",
      "props": {
        "text": "Activities that get your heart rate up and make you breathe harder."
      },
      "children": []
    },
    "aerobic_examples_text": {
      "type": "Text",
      "props": {
        "text": "Examples: Brisk walking, jogging, running, swimming, cycling, dancing, team sports (basketball, soccer)."
      },
      "children": []
    },
    "strength_training_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "strength_title_icon_stack",
        "strength_description",
        "strength_examples_text"
      ]
    },
    "strength_title_icon_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "icon_person_arms_up",
        "strength_title"
      ]
    },
    "icon_person_arms_up": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000127_01_3_person-arms-up.svg"
      },
      "children": []
    },
    "strength_title": {
      "type": "Text",
      "props": {
        "text": "Strength Training",
        "variant": "label"
      },
      "children": []
    },
    "strength_description": {
      "type": "Text",
      "props": {
        "text": "Exercises that build and maintain muscle mass."
      },
      "children": []
    },
    "strength_examples_text": {
      "type": "Text",
      "props": {
        "text": "Examples: Lifting weights, resistance band exercises, bodyweight exercises (push-ups, squats, planks)."
      },
      "children": []
    },
    "mind_body_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "mind_body_title",
        "mind_body_description",
        "mind_body_examples_text"
      ]
    },
    "mind_body_title": {
      "type": "Text",
      "props": {
        "text": "Mind-Body Practices",
        "variant": "label"
      },
      "children": []
    },
    "mind_body_description": {
      "type": "Text",
      "props": {
        "text": "Activities that combine physical postures, breathing techniques, and meditation or relaxation."
      },
      "children": []
    },
    "mind_body_examples_text": {
      "type": "Text",
      "props": {
        "text": "Examples: Yoga, Tai Chi, Pilates."
      },
      "children": []
    },
    "duration_frequency_h3": {
      "type": "Text",
      "props": {
        "text": "Duration and Frequency Guidelines",
        "variant": "h3"
      },
      "children": []
    },
    "duration_frequency_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "duration_aerobic",
        "duration_strength",
        "duration_consistency"
      ]
    },
    "duration_aerobic": {
      "type": "Text",
      "props": {
        "text": "Aerobic Activity: At least 150 minutes of moderate-intensity aerobic activity, or 75 minutes of vigorous-intensity aerobic activity, spread throughout the week."
      },
      "children": []
    },
    "duration_strength": {
      "type": "Text",
      "props": {
        "text": "Strength Training: Muscle-strengthening activities on 2 or more days a week, working all major muscle groups."
      },
      "children": []
    },
    "duration_consistency": {
      "type": "Text",
      "props": {
        "text": "Consistency: Regularity is key. Even short bursts of activity (e.g., 10-minute walks) can accumulate and contribute to overall well-being."
      },
      "children": []
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_cdc",
        "button_nami"
      ]
    },
    "button_cdc": {
      "type": "Button",
      "props": {
        "label": "Find Exercise Programs: CDC Physical Activity"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.cdc.gov/physicalactivity/basics/adults/index.htm"
          }
        }
      },
      "children": []
    },
    "button_nami": {
      "type": "Button",
      "props": {
        "label": "Mental Health Resources: NAMI"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.nami.org/help"
          }
        }
      },
      "children": []
    },
    "sources_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_list_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "source_who_stack",
        "source_cdc_stack"
      ]
    },
    "source_who_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "source_who_text",
        "source_who_button"
      ]
    },
    "source_who_text": {
      "type": "Text",
      "props": {
        "text": "World Health Organization (WHO): Physical Activity Guidelines"
      },
      "children": []
    },
    "source_who_button": {
      "type": "Button",
      "props": {
        "label": "View WHO Guidelines",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.who.int/news-room/fact-sheets/detail/physical-activity"
          }
        }
      },
      "children": []
    },
    "source_cdc_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "xs"
      },
      "children": [
        "source_cdc_text",
        "source_cdc_button"
      ]
    },
    "source_cdc_text": {
      "type": "Text",
      "props": {
        "text": "Centers for Disease Control and Prevention (CDC): Benefits of Physical Activity"
      },
      "children": []
    },
    "source_cdc_button": {
      "type": "Button",
      "props": {
        "label": "View CDC Benefits",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.cdc.gov/physicalactivity/basics/pa-health/index.htm"
          }
        }
      },
      "children": []
    }
  }
}
